def downsets(a):
    box = list(itertools.product(*[range(x) for x in a]))
    box.sort(key=lambda b: (sum(b), b))
    res = []
    def rec(i, cur):
        if i == len(box):
            res.append(frozenset(cur)); return
        b = box[i]
        rec(i+_sage_const_1 , cur)
        # can add b only if all predecessors in cur
        if all(tuple(b[:j]+(b[j]-_sage_const_1 ,)+b[j+_sage_const_1 :]) in cur for j in range(len(b)) if b[j] > _sage_const_0 ):
            cur.add(b); rec(i+_sage_const_1 , cur); cur.remove(b)
    rec(_sage_const_0 , set())
    return res

DS = {}
def mu(a, m, r):
    a = tuple(a)
    if a not in DS: DS[a] = downsets(a)
    best = None
    for D in DS[a]:
        if sum(_sage_const_1  for b in D if sum(b) > m) >= r:
            if best is None or len(D) < best: best = len(D)
    return best

def ghw_all(G):
    # G: k x N generator matrix over F_q; returns list d_1..d_k
    k, N = G.nrows(), G.ncols()
    best = [None]*(k+_sage_const_1 )
    cols = list(range(N))
    for size in range(N+_sage_const_1 ):
        for T in itertools.combinations(cols, size):
            comp = [c for c in cols if c not in T]
            rk = G.matrix_from_columns(comp).rank() if comp else _sage_const_0 
            dimT = k - rk
            for r in range(_sage_const_1 , dimT+_sage_const_1 ):
                if best[r] is None: best[r] = size
        if all(best[r] is not None for r in range(_sage_const_1 , k+_sage_const_1 )): break
    return best[_sage_const_1 :]

def eval_code(K, pts, d, nv):
    R = PolynomialRing(K, nv, 'x')
    mons = [R.monomial(*e) for e in itertools.product(range(d+_sage_const_1 ), repeat=nv) if sum(e) == d]
    G = matrix(K, [[mm(*p) for p in pts] for mm in mons])
    return G.matrix_from_rows(G.pivot_rows())

def proj_points(K, nv):
    pts = []
    for v in itertools.product(K, repeat=nv):
        v = vector(K, v)
        if v.is_zero(): continue
        i = min(j for j in range(nv) if v[j] != _sage_const_0 )
        if v[i] == _sage_const_1 : pts.append(tuple(v))
    return pts

def ci_from_points(K, nv, a, seedpts):
    # forms of degrees a through seedpts; return (forms, full zero set) if zero set is a reduced CI of size prod(a)
    R = PolynomialRing(K, nv, 'x')
    fs = []
    for deg in a:
        mons = [R.monomial(*e) for e in itertools.product(range(deg+_sage_const_1 ), repeat=nv) if sum(e) == deg]
        M = matrix(K, [[mm(*p) for mm in mons] for p in seedpts])
        ker = M.right_kernel()
        if ker.dimension() == _sage_const_0 : return None
        f = sum(c*mm for c, mm in zip(ker.random_element(), mons))
        if f == _sage_const_0 : return None
        fs.append(f)
    I = R.ideal(fs)
    if I.dimension() != _sage_const_1 : return None
    Z = [p for p in ALLPTS[(K.order(), nv)] if all(f(*p) == _sage_const_0  for f in fs)]
    if len(Z) != prod(a): return None
    return fs, Z

